def parse_duration(s: str) -> int:
    total_seconds = 0
    for part in s.split():
        if len(part) == 1:
            continue
        unit = part[-1].lower()
        value = int(part[:-1])
        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value
    return total_seconds
