def json_get(data, path: str, default=None):
    current = data
    for part in path.split('.'):
        try:
            current = current[int(part)]
        except (KeyError, IndexError, TypeError, ValueError):
            return default
        if not isinstance(current, (dict, list)):
            return default
    return current
